import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMarathaData(){const e=readFileSync(resolve(__dirname,"../../maratha-coinage-explorer/maratha-data.js"),"utf-8");return new Function(e+"\nreturn { MARATHA_INFO, COIN_TYPES, SCRIPT_DECODER_ITEMS, SYMBOL_HOTSPOTS, TERRITORY_MAP_REGIONS, TIMELINE_EVENTS, REFERENCES };")()}describe("Maratha Coinage Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadMarathaData()}),describe("MARATHA_INFO metadata",()=>{it("contains correct Maratha coinage attributes",()=>{expect(e.MARATHA_INFO.id).toBe("maratha-coinage"),expect(e.MARATHA_INFO.title).toContain("Maratha Coinage"),expect(e.MARATHA_INFO.period).toContain("1674"),expect(e.MARATHA_INFO.primaryScripts).toContain("Devanagari")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MARATHA_INFO.quickStats)).toBe(!0),expect(e.MARATHA_INFO.quickStats.length).toBe(6)})}),describe("COIN_TYPES & SCRIPT_DECODER_ITEMS",()=>{it("contains major Maratha coin types including Gold Hon & Shivrai",()=>{expect(Array.isArray(e.COIN_TYPES)).toBe(!0),expect(e.COIN_TYPES.length).toBeGreaterThanOrEqual(4);const t=e.COIN_TYPES.find(e=>"gold-hon"===e.id);expect(t).toBeDefined(),expect(t.obverseText).toContain("शिव"),expect(Array.isArray(e.SCRIPT_DECODER_ITEMS)).toBe(!0),expect(e.SCRIPT_DECODER_ITEMS.length).toBeGreaterThanOrEqual(4)})}),describe("SYMBOL_HOTSPOTS, TERRITORIES & TIMELINE",()=>{it("contains sacred symbols, territory regions, and historical timeline",()=>{expect(Array.isArray(e.SYMBOL_HOTSPOTS)).toBe(!0),expect(e.SYMBOL_HOTSPOTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.TERRITORY_MAP_REGIONS)).toBe(!0),expect(e.TERRITORY_MAP_REGIONS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4)})}),describe("REFERENCES",()=>{it("has non-empty references list",()=>{expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});